def request_status_data(db):
    ds = DatasetFactory()

    def make_request(status, created_date):
        obj = RequestFactory(status=status, dataset=ds)
        Request.objects.filter(pk=obj.pk).update(created=created_date)
        return obj

    for _ in range(3):
        make_request(Request.CREATED, date(2022, 12, 28))
    for _ in range(2):
        make_request(Request.CREATED, date(2023, 1, 3))

    for _ in range(2):
        make_request(Request.REJECTED, date(2022, 12, 28))
    for _ in range(1):
        make_request(Request.REJECTED, date(2023, 1, 3))

    return None


