@pytest.mark.haystack
@pytest.mark.django_db
@pytest.mark.parametrize("duration", DURATIONS)
@pytest.mark.parametrize("indicator", INDICATORS)
def test_request_status_stats_snapshot(app: DjangoTestApp, request_status_data, duration, indicator):
    with freeze_time(FROZEN_NOW):
        resp = app.get(
            reverse("request-stats-status"),
            params={"indicator": indicator, "duration": duration},
        )
    assert resp.status_code == 200
    snapshot = {
        "time_chart_data": json.dumps(resp.context["time_chart_data"]),
        "bar_chart_data": [
            {"display_value": str(b.get("display_value")), "count": b.get("count")}
            for b in resp.context["bar_chart_data"]
        ],
        "max_count": resp.context["max_count"],
    }
    assert len(snapshot["bar_chart_data"]) >= 2, (
        f"Expected ≥2 status buckets but got {len(snapshot['bar_chart_data'])}; "
        f"requests not faceted by status — check ES indexing"
    )
    assert normalize_chart_snapshot(snapshot) == normalize_chart_snapshot(EXPECTED[(indicator, duration)])


@pytest.mark.haystack
@pytest.mark.django_db
def test_request_status_stats_query_count(app: DjangoTestApp, request_status_data):
    with freeze_time(FROZEN_NOW):
        with CaptureQueriesContext(connection) as ctx:
            app.get(
                reverse("request-stats-status"),
                params={"indicator": "request-count", "duration": "duration-daily"},
            )

    request_queries = [q for q in ctx.captured_queries if '"request"' in q["sql"]]
    assert len(request_queries) <= 20, (
        f"Expected ≤20 request queries but got {len(request_queries)}. "
        f"The N+1 pattern may have been reintroduced (pre-refactor baseline was ~340)."
    )
